// The sites to watch. Add or remove clients here.
const sites = [
  { client: 'Echo Corp',          url: 'https://echocorp.co.za' },
  { client: 'Pro Level Coaching', url: 'https://prolevelhub.online' },
];
return sites.map(s => ({ json: s }));

// Compare each site with its last known state so you only get alerted when something changes
const sites = $('Client sites').all();
const state = $getWorkflowStaticData('global');
state.sites = state.sites || {};
const alerts = [];
$input.all().forEach((item, i) => {
  const { client, url } = sites[i].json;
  const status = item.json.statusCode;
  const up = !item.json.error && status >= 200 && status < 400;
  const was = state.sites[url];
  if (was === undefined) { state.sites[url] = up; return; }   // first run: just record
  if (was !== up) {
    alerts.push({ json: {
      message: up
        ? `✅ ${client} is back up (${url})`
        : `🚨 ${client} is DOWN (${url}): ${item.json.error ? 'no response' : 'HTTP ' + status}`,
    }});
  }
  state.sites[url] = up;
});
if (!alerts.length) return [];  // nothing changed = no alert
const lines = alerts.map(a => `<li>${a.json.message}</li>`).join('');
return [{ json: { subject: alerts.length === 1 ? alerts[0].json.message : `${alerts.length} site status changes`,
  html: `<h3 style="font-family:sans-serif">Echo uptime monitor</h3><ul style="font-family:sans-serif">${lines}</ul>` } }];
